<?php
$allDetailed=$coordProgrammeTypes?safeRun($pdo,"SELECT dr.*,(SELECT COALESCE(SUM(max_marks),0) FROM detailed_rubric_criteria dc WHERE dc.detailed_rubric_id=dr.id) total_marks FROM detailed_rubrics dr WHERE dr.status='published' AND dr.programme_type IN (".implode(',',array_fill(0,count($coordProgrammeTypes),'?')).") AND dr.id=(SELECT dr2.id FROM detailed_rubrics dr2 WHERE dr2.programme_type=dr.programme_type AND dr2.evaluator_role=dr.evaluator_role AND dr2.status='published' ORDER BY dr2.published_at DESC,dr2.id DESC LIMIT 1) ORDER BY FIELD(dr.programme_type,'diploma_fyp1','diploma_fyp2','degree_fyp1','degree_fyp2'),FIELD(dr.evaluator_role,'coordinator','supervisor','report_panel','presentation_panel')",$coordProgrammeTypes)->fetchAll():[];
$selectedId=(int)($_GET['detailed_id']??($allDetailed[0]['id']??0));$selected=null;foreach($allDetailed as $dr)if((int)$dr['id']===$selectedId)$selected=$dr;$criteria=$selected?safeRun($pdo,'SELECT * FROM detailed_rubric_criteria WHERE detailed_rubric_id=? ORDER BY sort_order,id',[$selectedId])->fetchAll():[];$total=(float)array_sum(array_map('floatval',array_column($criteria,'max_marks')));$editing=($_GET['edit']??'')==='1';
?>
<?php if(($_GET['rubricmsg']??'')==='updated'): ?><div class="alert alert-success small">Detailed rubric updated.</div><?php endif; ?>
<div class="row g-3"><div class="col-lg-4"><div class="card-fy"><div class="section-title">Detailed Rubrics</div><?php foreach($allDetailed as $dr): ?><a href="?view=rubrics&section=detailed&detailed_id=<?= (int)$dr['id'] ?>" class="d-block text-decoration-none p-3 rounded-3 mb-2" style="border:1.5px solid <?= $selectedId===(int)$dr['id']?'var(--theme)':'#eee' ?>"><strong class="small text-dark"><?= e(roleLabel($dr['evaluator_role'])) ?></strong><div class="small text-muted"><?= e(programmeTypeLabel($dr['programme_type'])) ?> · Total marks <?= e(rtrim(rtrim(number_format((float)$dr['total_marks'],2,'.',''),'0'),'.')) ?></div></a><?php endforeach; ?><?php if(!$allDetailed): ?><p class="small text-muted">No detailed rubrics are available.</p><?php endif; ?></div></div>
<div class="col-lg-8"><?php if($selected): ?><div class="card-fy"><div class="d-flex justify-content-between align-items-start gap-3 flex-wrap"><div><div class="section-title mb-1"><?= e(roleLabel($selected['evaluator_role'])) ?> Detailed Rubric</div><div class="small text-muted"><?= e(programmeTypeLabel($selected['programme_type'])) ?></div></div><strong class="fs-5" id="detailedTotal">Total marks: <?= e(rtrim(rtrim(number_format($total,2,'.',''),'0'),'.')) ?></strong></div>
<?php if(!$editing): ?><div class="table-responsive mt-3"><table class="table-fy"><thead><tr><th>Criterion and Description</th><th>Maximum</th></tr></thead><tbody><?php foreach($criteria as $c): ?><tr><td><strong><?= e($c['criterion_name']) ?></strong><?php if($c['description']): ?><div class="small text-muted"><?= e($c['description']) ?></div><?php endif; ?></td><td><?= e(number_format((float)$c['max_marks'],1)) ?>/10</td></tr><?php endforeach; ?></tbody></table></div><a href="?view=rubrics&section=detailed&detailed_id=<?= $selectedId ?>&edit=1" class="btn-fy-orange mt-3"><i class="fa-solid fa-pen me-1"></i>Edit</a>
<?php else: ?><form method="post"><?= csrfField() ?><input type="hidden" name="action" value="update_published_detailed_rubric"><input type="hidden" name="detailed_rubric_id" value="<?= $selectedId ?>"><div id="existingDetailedCriteria" class="mt-3"><?php foreach($criteria as $c): ?><div class="row g-2 align-items-end mb-3"><div class="col-md-5"><label class="form-label small fw-semibold">Criterion</label><input required maxlength="200" name="criterion_name[<?= (int)$c['id'] ?>]" value="<?= e($c['criterion_name']) ?>" class="form-control-fy w-100"></div><div class="col-md-5"><label class="form-label small fw-semibold">Description</label><textarea name="description[<?= (int)$c['id'] ?>]" class="form-control-fy w-100" rows="2"><?= e($c['description']??'') ?></textarea></div><div class="col-md-2"><label class="form-label small fw-semibold">Marks: <output class="detailed-output"><?= e((string)(float)$c['max_marks']) ?></output></label><input type="range" min="0" max="10" step="0.5" name="max_marks[<?= (int)$c['id'] ?>]" value="<?= e((string)$c['max_marks']) ?>" class="w-100 detailed-weight"></div></div><?php endforeach; ?></div><div id="newDetailedCriteria"></div><button type="button" id="addDetailedCriterion" class="btn-fy-outline"><i class="fa-solid fa-plus me-1"></i>Add Criterion</button><div class="d-flex gap-2 mt-3"><button class="btn-fy-orange">Update</button><a class="btn-fy-outline" href="?view=rubrics&section=detailed&detailed_id=<?= $selectedId ?>">Cancel</a></div></form><?php endif; ?></div><?php else: ?><div class="card-fy text-center text-muted py-5">No detailed rubric selected.</div><?php endif; ?></div></div>
<script>(function(){const box=document.getElementById('newDetailedCriteria'),btn=document.getElementById('addDetailedCriterion'),total=document.getElementById('detailedTotal');function recalc(){let sum=0;document.querySelectorAll('.detailed-weight').forEach(x=>{sum+=Number(x.value||0);const o=x.parentElement.querySelector('.detailed-output');if(o)o.textContent=x.value;});if(total)total.textContent='Total marks: '+(Number.isInteger(sum)?sum.toFixed(0):sum.toFixed(2).replace(/0+$/,'').replace(/\.$/,''));}btn?.addEventListener('click',()=>{const row=document.createElement('div');row.className='row g-2 align-items-end mb-3';row.innerHTML='<div class="col-md-5"><label class="form-label small fw-semibold">New criterion</label><input required maxlength="200" name="new_criterion_name[]" class="form-control-fy w-100"></div><div class="col-md-5"><label class="form-label small fw-semibold">Description</label><textarea name="new_description[]" class="form-control-fy w-100" rows="2"></textarea></div><div class="col-md-2"><label class="form-label small fw-semibold">Marks: <output class="detailed-output">0</output></label><input type="range" min="0" max="10" step="0.5" name="new_max_marks[]" value="0" class="w-100 detailed-weight"></div>';box.appendChild(row);row.querySelector('.detailed-weight').addEventListener('input',recalc);recalc();});document.querySelectorAll('.detailed-weight').forEach(x=>x.addEventListener('input',recalc));})();</script>
